def transform(grid):
    out = [row[:] for row in grid]
    # In rows containing the foreground pattern, recolor the trailing background
    # run beyond its rightmost foreground cell to 1.
    bg = max(set(v for row in grid for v in row), key=lambda v: sum(row.count(v) for row in grid))
    for r, row in enumerate(grid):
        foreground = [c for c, value in enumerate(row) if value != bg]
        if foreground:
            for c in range(max(foreground) + 1, len(row)):
                out[r][c] = 1
    return out

